theorem my_favorite_thm : 
  let sam_outcomes : Finset ℕ := {1, 2, 3, 4}
  let tyler_outcomes : Finset ℕ := {1, 2, 3, 4, 5, 6}
  let favorable_outcomes := 
    (sam_outcomes ×ˢ tyler_outcomes).filter (fun (s, t) => s > t)
  (favorable_outcomes.card : ℚ) / (sam_outcomes.card * tyler_outcomes.card) = 1/4

theorem my_favorite_thm : 
  let x_range := ({-4, -3, -2, -1, 0, 1, 2, 3, 4} : Finset ℤ)
  let y_range := ({-3, -2, -1, 0, 1, 2, 3} : Finset ℤ)
  (x_range.card * y_range.card = 63)

theorem my_favorite_theorem : 
  let T : ℝ := 20
  let roots := {x : ℝ | x^2 - 3*T*x + T^2 = 0}
  roots = {(T*(3 + Real.sqrt 5))/2, (T*(3 - Real.sqrt 5))/2}
